111	    /**
112	     * Returns the {@link DnsResponseCode} that corresponds with the given {@code responseCode}.
113	     *
114	     * @param responseCode the DNS RCODE
115	     *
116	     * @return the corresponding {@link DnsResponseCode}
117	     */
118	    public static DnsResponseCode valueOf(int responseCode) {
119	        switch (responseCode) {
120	        case 0:
121	            return NOERROR;
122	        case 1:
123	            return FORMERR;
124	        case 2:
125	            return SERVFAIL;
126	        case 3:
127	            return NXDOMAIN;
128	        case 4:
129	            return NOTIMP;
130	        case 5:
131	            return REFUSED;
132	        case 6:
133	            return YXDOMAIN;
134	        case 7:
135	            return YXRRSET;
136	        case 8:
137	            return NXRRSET;
138	        case 9:
139	            return NOTAUTH;
140	        case 10:
141	            return NOTZONE;
142	        case 16:
143	            return BADVERS_OR_BADSIG;
144	        case 17:
145	            return BADKEY;
146	        case 18:
147	            return BADTIME;
148	        case 19:
149	            return BADMODE;
150	        case 20:
151	            return BADNAME;
152	        case 21:
153	            return BADALG;
154	        default:
155	            return new DnsResponseCode(responseCode);
156	        }
157	    }
